WITH flattened_attrs AS (SELECT id, created_at, coupon_codes, items, attributes, ARRAY_JOIN(ARRAY_SORT(coupon_codes), ',') AS coupons_text, TRANSFORM(FILTER(items, li -> li.promo IS NOT NULL), li -> STRUCT(li.product_id AS pid, ROUND(li.price * 0.9, 2) AS discounted_price)) AS promo_lines FROM carts WHERE ARRAY_CONTAINS(coupon_codes, 'BUNDLE')) SELECT DATE_TRUNC('HOUR', created_at) AS hour_window, MAX(created_at) AS ended_at, (UNIX_TIMESTAMP(MAX(created_at)) - UNIX_TIMESTAMP(MIN(created_at))) / 60 AS span_minutes, (UNIX_TIMESTAMP(MAX(created_at)) - UNIX_TIMESTAMP(MIN(created_at))) / 60 AS span_minutes_2 FROM flattened_attrs GROUP BY hour_window HAVING span_minutes_2 > 0;
